    priority = (2, 3, 0, 1)
    out = []
    for r in range(4):
        line = []
        for c in range(4):
            value = 0
            for k in priority:
                if panels[k][r][c] != 0:
                    value = panels[k][r][c]
                    break
            line.append(value)
        out.append(line)
    return out
